add('is-websocket','exact/API','Which Context API recognizes WebSocket upgrade headers without performing a handshake?', 'Context.IsWebsocket requires Connection to contain upgrade ignoring case and Upgrade to equal websocket ignoring case.',[('context.go','func (c *Context) IsWebsocket','Context.IsWebsocket')])
