add('multipart-file-chain','crossfile','Trace multipart form binding to file-header assignment for an array of uploads.', 'formMultipartBinding.Bind parses multipart data then mappingByPtr uses multipartRequest; mapping reaches TrySet, which selects MultipartForm.File and setByMultipartFormFile; array assignment checks exact length and recursively sets each file slot.',[('binding/form.go','func (formMultipartBinding) Bind(','formMultipartBinding.Bind'),('binding/form_mapping.go','func mappingByPtr','mappingByPtr'),('binding/form_mapping.go','func mapping(','mapping'),('binding/form_mapping.go','func tryToSetValue','tryToSetValue'),('binding/multipart_form_mapping.go','func (r *multipartRequest) TrySet','multipartRequest.TrySet'),('binding/multipart_form_mapping.go','func setByMultipartFormFile','setByMultipartFormFile'),('binding/multipart_form_mapping.go','func setArrayOfMultipartFormFiles','setArrayOfMultipartFormFiles')],[(0,1,'calls with multipartRequest'),(1,2,'calls'),(2,3,'calls'),(3,4,'setter dispatch'),(4,5,'file data assignment'),(5,6,'array case'),(6,5,'recursive slot assignment')])
add('attachment-filename-chain','crossfile','How does FileAttachment choose and produce an ASCII versus UTF-8 Content-Disposition filename?', 'FileAttachment calls isASCII; ASCII names are quoted after escapeQuotes, which uses quoteEscaper to escape backslash and quote; non-ASCII names use filename*=UTF-8 with url.QueryEscape.',[('context.go','func (c *Context) FileAttachment','Context.FileAttachment'),('utils.go','func isASCII','isASCII'),('context.go','func escapeQuotes','escapeQuotes')],[(0,1,'ASCII predicate'),(0,2,'ASCII filename escaping')])
add('html-render-error-chain','crossfile','What happens when Context.HTML is used without a configured HTML renderer?', 'Context.HTML calls Context.Render with an empty render.HTML; HTML.Render sets content type then returns errHTMLRendererNotConfigured on nil Template; Context.Render records the error and aborts.',[('context.go','func (c *Context) HTML(','Context.HTML'),('context.go','func (c *Context) Render(','Context.Render'),('render/html.go','func (r HTML) Render','HTML.Render'),('context.go','func (c *Context) Error(','Context.Error'),('context.go','func (c *Context) Abort()','Context.Abort')],[(0,1,'calls with empty HTML'),(1,2,'Render dispatch'),(2,1,'error return'),(1,3,'records render error'),(1,4,'aborts')])
add('collection-format-error','config/error','Which collection_format values are supported in form splitting and what happens for an unsupported value?', 'Empty or multi passes original values; csv, ssv, tsv, pipes split on comma, space, tab, pipe respectively; an unknown format returns an error naming supported formats.',[('binding/form_mapping.go','func trySplit','trySplit')])
add('trusted-proxy-invalid','config/error','How does prepareTrustedCIDRs process single IP addresses and reject invalid trusted-proxy entries?', 'Bare IPv4 gets /32 and IPv6 gets /128; unparseable bare IP returns net.ParseError with type IP address; invalid CIDR returns net.ParseCIDR error; nil trustedProxies returns nil,nil.',[('gin.go','func (engine *Engine) prepareTrustedCIDRs','Engine.prepareTrustedCIDRs'),('gin.go','func parseIP(','parseIP')])
add('no-json-adapter-precedence','hardnegative/noanswer','Within codec/json/go_json.go and codec/json/jsoniter.go, find a runtime selector that resolves both adapters being compiled by choosing one by priority.', 'No runtime conflict selector exists in these two files: separate go_json and jsoniter build tags each define Package and init assigning API. These scopes contain delegation wrappers, not runtime priority resolution.',[('codec/json/go_json.go','func init()','gojson.init'),('codec/json/jsoniter.go','func init()','jsoniter.init')],no=True)
